"""IMPORT SOURCE MDL — standalone Blender Text Editor importer.

Open this ONE file in Blender 5.2 on Windows x64 and Run Script. Choose an MDL.
Or fill MODEL_PATH below and run to import directly. F3: Import Source MDL.
No installed SourceIO, pip packages, SFM, or dmxconvert are needed.
The required SourceIO Python code, Windows texture/archive decoder, shader
groups, and eye templates are EMBEDDED in this file. They unpack automatically
into a versioned temporary cache; no files beside this script are required.

Your model ASSETS are still needed: MDL plus its matching VVD/VTX and referenced
VMT/VTF files (loose or in mounted game VPKs). Keep their models/materials paths.
The importer discovers nearby gameinfo/SFM content. Add CONTENT_ROOTS if assets
live elsewhere; entries can be game folders, gameinfo.txt files or *_dir.vpk.

Source1 MDL versions 36-49 are dispatched by the bundled SourceIO parsers.
Tested in Blender 5.2.2 with TF2 Scout, HWM Scout, and Half-Life 2 Alyx.
Source2 VMDL, maps, animation clips and SourceIO's custom flex-control UI are
outside this MDL model importer. Skeletons, weights, raw facial shape keys,
bodygroups, materials, packed textures and independently movable eyes import.
Rotate the eye empties to aim the pupils; they follow their head/eye bones.

Textures are packed into the blend. Eye drivers use ordinary Blender transform
variables, no custom Python functions; saved models do not need this importer.
The blend is not saved automatically. Ctrl-Z undoes the import operator.
Missing materials/textures are listed in 'Standalone MDL Import Report'.

SourceIO copyright (c) 2020 REDxEYE; MIT license reproduced below and in payload.
This private MDL bundle does not modify or register the installed SourceIO add-on.
"""
MODEL_PATH = ''
CONTENT_ROOTS = ()  # Example: (r'D:\SFM\game\usermod', r'D:\SFM\game\tf')
IMPORT_SCALE = 0.0254  # Source inches to Blender meters. Use 1.0 for Source units.
USE_SOURCE_SHADERS = True
IMPORT_PHYSICS = False

import base64
import hashlib
import importlib
import importlib.util
import io
import json
import math
from pathlib import Path
import struct
import sys
import tempfile
import uuid
import zipfile
import bpy
from bpy.props import BoolProperty, CollectionProperty, FloatProperty, StringProperty
from bpy_extras.io_utils import ImportHelper

_PACKAGE = '_mdl_standalone_sourceio'


def _bootstrap():
    if sys.platform != 'win32' or struct.calcsize('P') != 8:
        raise RuntimeError('This self-contained build includes the Windows x64 decoder. Use Windows x64 Blender.')
    if bpy.app.version < (4, 4, 0):
        raise RuntimeError('Use Blender 4.4 or newer; this build was tested in Blender 5.2.')
    loaded = sys.modules.get(_PACKAGE)
    if loaded and getattr(loaded, '_bundle_digest', None) == BUNDLE_SHA256:
        return Path(loaded.__file__).parent
    raw = base64.b85decode(BUNDLE_B85)
    if hashlib.sha256(raw).hexdigest() != BUNDLE_SHA256:
        raise RuntimeError('Embedded importer checksum failed; the script is incomplete or was modified.')
    cache = Path(tempfile.gettempdir()) / 'StandaloneSourceMDL' / BUNDLE_SHA256[:20] / _PACKAGE
    cache.mkdir(parents=True, exist_ok=True)
    cache = cache.resolve()
    with zipfile.ZipFile(io.BytesIO(raw)) as archive:
        manifest = json.loads(archive.read('MANIFEST.json'))
        for name, digest in manifest.items():
            target = (cache / name).resolve()
            if not target.is_relative_to(cache):
                raise RuntimeError('Invalid embedded resource path: ' + name + ' -> ' + str(target))
            if target.is_file() and hashlib.sha256(target.read_bytes()).hexdigest() == digest:
                continue
            data = archive.read(name)
            if hashlib.sha256(data).hexdigest() != digest:
                raise RuntimeError('Embedded resource checksum failed: ' + name)
            target.parent.mkdir(parents=True, exist_ok=True)
            temporary = target.with_name(target.name + '.' + uuid.uuid4().hex + '.tmp')
            temporary.write_bytes(data)
            try:
                temporary.replace(target)
            except OSError:
                # A second Blender process can finish the same extraction and
                # load the native module before this one commits its copy.
                if target.is_file() and hashlib.sha256(target.read_bytes()).hexdigest() == digest:
                    temporary.unlink(missing_ok=True)
                else:
                    raise
    for name in list(sys.modules):
        if name == _PACKAGE or name.startswith(_PACKAGE + '.'):
            del sys.modules[name]
    spec = importlib.util.spec_from_file_location(_PACKAGE, cache / '__init__.py', submodule_search_locations=[str(cache)])
    package = importlib.util.module_from_spec(spec)
    sys.modules[_PACKAGE] = package
    spec.loader.exec_module(package)
    package._bundle_digest = BUNDLE_SHA256
    return cache


def _module(suffix):
    return importlib.import_module(_PACKAGE + '.' + suffix)


def _load_shader_assets(cache):
    resource = cache / 'blender_bindings/assets/sycreation-s-default.blend'
    required = ('SIO_eye_template', 'SIO_simple_eye_template')
    assets = _module('blender_bindings.material_loader.standalone_assets')
    assets.NODE_GROUPS.clear(); assets.MATERIALS.clear()
    for group in bpy.data.node_groups:
        if group.get('standalone_mdl_bundle') == BUNDLE_SHA256:
            assets.NODE_GROUPS[group['standalone_mdl_original_name']] = group
    for mat in bpy.data.materials:
        if mat.get('standalone_mdl_template_bundle') == BUNDLE_SHA256:
            assets.MATERIALS[mat['standalone_mdl_original_name']] = mat
    with bpy.data.libraries.load(str(resource), link=False) as (available, requested):
        group_names = list(available.node_groups)
        if all(n in assets.MATERIALS for n in required) and all(n in assets.NODE_GROUPS for n in group_names):
            return
        requested.node_groups = list(group_names)
        requested.materials = list(required)
    for original, group in zip(group_names, requested.node_groups):
        if group is None: continue
        group.name = 'SMDL ' + original
        group.use_fake_user = True
        group['standalone_mdl_bundle'] = BUNDLE_SHA256
        group['standalone_mdl_original_name'] = original
        assets.NODE_GROUPS[original] = group
    for original, mat in zip(required, requested.materials):
        if mat is None: continue
        mat.name = 'SMDL ' + original
        mat['standalone_mdl_template_bundle'] = BUNDLE_SHA256
        mat['standalone_mdl_original_name'] = original
        mat.use_fake_user = True
        assets.MATERIALS[original] = mat
    if any(n not in assets.MATERIALS for n in required):
        raise RuntimeError('Embedded Source eye templates could not be loaded')


def _mounted_content(filepath, content_roots):
    ContentManager = _module('library.shared.content_manager').ContentManager
    TinyPath = _module('library.utils.tiny_path').TinyPath
    Loose = _module('library.shared.content_manager.providers.loose_files').LooseFilesContentProvider
    manager = ContentManager()
    manager.clean(); manager.first_import = None; manager.priority_list = None
    preferred = []
    warnings = []
    # Explicit roots are mounted in user order and searched first.
    for entry in content_roots:
        path = Path(bpy.path.abspath(str(entry))).expanduser().resolve()
        if not path.exists():
            warnings.append('Content root does not exist: ' + str(path)); continue
        previous = set(manager.children)
        if path.is_dir():
            provider = Loose(TinyPath(str(path))); manager.add_child(provider); preferred.append(provider)
        manager.scan_for_content(TinyPath(str(path)))
        if path.is_file():
            preferred.extend(sorted(manager.children-previous-set(preferred), key=lambda p:str(p.filepath).lower()))
    try:
        manager.scan_for_content(TinyPath(str(filepath)))
    except (OSError, ValueError, AttributeError) as exc:
        warnings.append('Automatic content discovery: ' + str(exc))
    # Deterministic local roots before unrelated discovered game providers.
    local_roots = [parent.parent for parent in filepath.parents if parent.name.lower() == 'models']
    local_roots.append(filepath.parent)
    for path in local_roots:
        provider = Loose(TinyPath(str(path)))
        manager.add_child(provider)
        if provider not in preferred: preferred.append(provider)
    remaining = sorted(manager.children-set(preferred), key=lambda p:str(p.filepath).lower())
    manager.priority_list = preferred + remaining
    manager.first_import = TinyPath(str(filepath))
    return manager, warnings


def _material_images(material, seen=None):
    seen = set() if seen is None else seen
    images = set()
    def walk(tree):
        if tree is None or tree.as_pointer() in seen: return
        seen.add(tree.as_pointer())
        for node in tree.nodes:
            image = getattr(node, 'image', None)
            if image: images.add(image)
            walk(getattr(node, 'node_tree', None))
    walk(material.node_tree)
    return images


def _report_import(filepath, container, warnings, mounts):
    meshes = list(container.objects)
    materials = {slot.material for obj in meshes for slot in obj.material_slots if slot.material}
    images = set()
    for mat in materials:
        images.update(_material_images(mat))
        if mat.get('mdl_import_error'):
            warnings.append(f'Material {mat.name}: {mat["mdl_import_error"]}')
        if not mat.use_nodes or not mat.node_tree or not any(n.type == 'OUTPUT_MATERIAL' and n.inputs.get('Surface') and n.inputs['Surface'].is_linked for n in mat.node_tree.nodes):
            warnings.append('No connected surface shader: ' + mat.name)
    # Packed FILE images decode lazily. Force pixel loading before reporting
    # has_data, otherwise perfectly valid new VTF images look falsely missing.
    for img in images:
        if img.get('standalone_missing_texture'):
            warnings.append('Missing texture placeholder: ' + img['standalone_missing_texture'])
        if img.size[0] and img.size[1]:
            try: _ = img.pixels[0]
            except (IndexError, RuntimeError): pass
    eyes = [o for o in container.attachments if o.get('standalone_mdl_eye')]
    for obj in meshes:
        warnings.extend(json.loads(obj.get('standalone_mdl_eye_warnings', '[]')))
    for eye in eyes:
        mat = eye.get('eye_material')
        iris = mat.node_tree.nodes.get('$Iris') if mat and mat.node_tree else None
        if iris is None or not getattr(iris, 'image', None) or not iris.image.has_data:
            warnings.append('Missing iris texture for eye: ' + eye.name)
    for img in images:
        if not img.has_data:
            warnings.append('Image has no decoded pixels: ' + img.name)
        elif not img.packed_file:
            try: img.pack()
            except RuntimeError as exc: warnings.append(f'Could not pack {img.name}: {exc}')
    shape_keys = sum(max(0, len(obj.data.shape_keys.key_blocks)-1) for obj in meshes if obj.type=='MESH' and obj.data.shape_keys)
    report = {'model':str(filepath), 'collection':container.master_collection.name,
              'armature':container.armature.name if container.armature else None,
              'meshes':[o.name for o in meshes], 'vertices':sum(len(o.data.vertices) for o in meshes if o.type=='MESH'),
              'materials':sorted(m.name for m in materials), 'images':sorted(i.name for i in images),
              'shape_keys':shape_keys, 'eyes':[o.name for o in eyes],
              'content_mounts':[str(p.filepath) for p in mounts],
              'warnings':sorted(set(warnings)), 'self_contained':True,
              'notes':['Textures are packed; the original asset files were not modified.',
                       'Rotate the eye empties to aim the pupils. Facial shapes are editable shape keys.',
                       'Bodygroup meshes are imported as separate collections; hide alternatives as needed.']}
    text = bpy.data.texts.get('Standalone MDL Import Report') or bpy.data.texts.new('Standalone MDL Import Report')
    text.clear(); text.write(json.dumps(report, indent=2, ensure_ascii=False))
    container.master_collection['standalone_mdl_report'] = json.dumps(report, ensure_ascii=False)
    return report


def import_mdl_file(filepath, content_roots=(), scale=0.0254, use_source_shaders=True, import_physics=False,
                    import_textures=True):
    filepath = Path(bpy.path.abspath(str(filepath))).expanduser().resolve()
    if not filepath.is_file(): raise ValueError('MDL file not found: ' + str(filepath))
    with filepath.open('rb') as handle: header = handle.read(8)
    if len(header)!=8: raise ValueError('The model file is incomplete')
    magic, version = struct.unpack('<4sI', header)
    if magic!=b'IDST' or not 36 <= version <= 49:
        raise ValueError(f'This build supports Source1 IDST MDL v36-49; file is {magic!r} v{version}')
    if not math.isfinite(scale) or scale <= 0: raise ValueError('Scale must be positive and finite')
    if bpy.context.mode != 'OBJECT': raise ValueError('Switch to Object Mode before importing')
    cache = _bootstrap()
    # Capture state for local rollback if parsing/geometry creation fails.
    kinds = ('objects','meshes','armatures','materials','images','node_groups','collections')
    before = {kind:set(getattr(bpy.data,kind)) for kind in kinds}
    selected = list(bpy.context.selected_objects)
    active = bpy.context.view_layer.objects.active
    manager = None
    try:
        _load_shader_assets(cache)
        manager, warnings = _mounted_content(filepath, content_roots)
        bpy_utils = _module('blender_bindings.utils.bpy_utils')
        # Each import is independent, including the same MDL with different
        # roots or shader settings. Only reuse textures inside this import.
        scope = str(filepath).casefold() + '#' + uuid.uuid4().hex
        bpy_utils.MDL_IMPORT_SCOPE = scope
        _module('blender_bindings.utils.texture_utils').MDL_IMPORT_SCOPE = scope
        options = _module('blender_bindings.operators.import_settings_base').ModelOptions.default()
        options.scale = scale; options.import_textures = bool(import_textures); options.use_bvlg = bool(use_source_shaders)
        options.create_flex_drivers = False; options.import_animations = False
        options.import_physics = bool(import_physics); options.bodygroup_grouping = True
        utils = _module('library.utils')
        TinyPath = _module('library.utils.tiny_path').TinyPath
        # Record actual texture lookup failures, not every speculative VMT path.
        shader_cls = _module('blender_bindings.material_loader.shaders.source1_shader_base').Source1ShaderBase
        old_load = shader_cls.load_texture
        def tracked_load(self, name, path):
            image = old_load(self, name, path)
            if image is None: warnings.append('Missing texture: ' + str(path/name) + '.vtf')
            return image
        shader_cls.load_texture = tracked_load
        try:
            with utils.FileBuffer(TinyPath(str(filepath))) as stream:
                container = _module('blender_bindings.models').import_model(TinyPath(str(filepath)), stream, manager, options)
        finally:
            shader_cls.load_texture = old_load
        if container is None or not container.objects:
            raise RuntimeError('No meshes were created from the selected MDL')
        _module('blender_bindings.models.common').put_into_collections(container, filepath.stem, bodygroup_grouping=True)
        bpy.context.view_layer.update()
        for obj in bpy.context.selected_objects: obj.select_set(False)
        target = container.armature or container.objects[0]
        target.select_set(True); bpy.context.view_layer.objects.active = target
        report = _report_import(filepath, container, warnings, manager.priority_list or manager.children)
        print('STANDALONE_MDL_IMPORTED', filepath.name, len(report['meshes']), 'meshes,', len(report['eyes']), 'eyes,', len(report['warnings']), 'warnings')
        return report
    except Exception:
        if bpy.context.object and bpy.context.object.mode != 'OBJECT':
            bpy.ops.object.mode_set(mode='OBJECT')
        for kind in kinds:
            collection = getattr(bpy.data, kind)
            for block in list(set(collection)-before[kind]):
                try: collection.remove(block, do_unlink=True)
                except (TypeError, RuntimeError):
                    if block.users == 0: collection.remove(block)
        for obj in selected:
            if obj.name in bpy.context.view_layer.objects: obj.select_set(True)
        if active and active.name in bpy.context.view_layer.objects: bpy.context.view_layer.objects.active = active
        raise
    finally:
        if manager is not None:
            manager.first_import = None; manager.priority_list = None


class IMPORT_SCENE_OT_standalone_source_mdl(bpy.types.Operator, ImportHelper):
    bl_idname = 'import_scene.standalone_source_mdl'
    bl_label = 'Import Source MDL'
    bl_description = 'Import MDL model, textures, facial shapes and working eyes; no SourceIO installation needed'
    bl_options = {'REGISTER', 'UNDO'}
    filename_ext = '.mdl'
    filter_glob: StringProperty(default='*.mdl', options={'HIDDEN'})
    files: CollectionProperty(type=bpy.types.OperatorFileListElement)
    content_root: StringProperty(name='Extra content folder', subtype='DIR_PATH', description='Optional folder containing models/materials; nearby game content is discovered automatically')
    scale: FloatProperty(name='Scale', default=0.0254, min=0.000001, precision=6)
    source_shaders: BoolProperty(name='Source shader groups', default=True)
    physics: BoolProperty(name='Physics mesh', default=False)

    def execute(self, context):
        paths = [Path(self.filepath).parent / f.name for f in self.files] or [Path(self.filepath)]
        roots = tuple(CONTENT_ROOTS) + ((self.content_root,) if self.content_root else ())
        warnings = 0; imported = 0; errors = []
        for path in paths:
            try:
                report = import_mdl_file(path, roots, self.scale, self.source_shaders, self.physics)
                warnings += len(report['warnings'])
                imported += 1
            except Exception as exc:
                import traceback
                traceback.print_exc()
                errors.append(path.name + ': ' + str(exc))
        if errors: self.report({'WARNING'} if imported else {'ERROR'}, '; '.join(errors))
        if imported:
            if warnings:
                self.report({'WARNING'}, f'Imported {imported} model(s); {warnings} resource warnings. See Standalone MDL Import Report.')
            else: self.report({'INFO'}, f'Imported {imported} model(s), including materials and eyes')
        return {'FINISHED'} if imported else {'CANCELLED'}


def register():
    previous = getattr(bpy.types, 'IMPORT_SCENE_OT_standalone_source_mdl', None)
    if previous: bpy.utils.unregister_class(previous)
    bpy.utils.register_class(IMPORT_SCENE_OT_standalone_source_mdl)


def run():
    if MODEL_PATH:
        return bpy.ops.import_scene.standalone_source_mdl('EXEC_DEFAULT', filepath=MODEL_PATH,
            scale=IMPORT_SCALE, source_shaders=USE_SOURCE_SHADERS, physics=IMPORT_PHYSICS)
    if bpy.app.background:
        raise ValueError('Set MODEL_PATH or call import_mdl_file() for a background import')
    return bpy.ops.import_scene.standalone_source_mdl('INVOKE_DEFAULT', scale=IMPORT_SCALE,
        source_shaders=USE_SOURCE_SHADERS, physics=IMPORT_PHYSICS)


